const today = new Date();
const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
const dayOfMonth = today.getDate();
const daysRemaining = daysInMonth - dayOfMonth + 1;
const expectedPaceRatio = dayOfMonth / daysInMonth;
const todayISO = today.toISOString().split('T')[0];
// === DAY-OF-WEEK BUDGET MULTIPLIERS (Bill's Final v2) ===
// JS getDay(): 0 = Sunday ... 6 = Saturday
const DOW_MULTIPLIERS = {
  0: -0.26, // Sunday    — weakest day (-36%)
  1:  0.20, // Monday    — strongest day (+22.5% lift)
  2: -0.04, // Tuesday   — below average, good CPA
  3:  0.05, // Wednesday — solid day
  4:  0.08, // Thursday  — very efficient
  5:  0.03, // Friday    — above average
  6: -0.18  // Saturday  — weak day (-22.9%)
};
// Date the DOW system first goes live. Budgets set before this date were
// NOT day-of-week shaped, so yesterday-multiplier de-normalization is
// skipped for any day before it.
const DOW_ENABLED_SINCE = '2026-06-16'; // <-- SET TO ACTUAL GO-LIVE DATE
const pacingItem = $input.item.json;
const editItem = $('Edit Fields').item.json;
const practiceName = editItem.practiceName || 'Unknown practice';
const adsId = editItem.adsId;
const hubspotMonthlyBudget = Number(editItem.monthlyBudget || 0);
const rawResults = Array.isArray(pacingItem.results) ? pacingItem.results : [];

const adsIdForSpend = String(adsId || '').trim();
// Enabled-only sum = the OLD (under-counting) number. Kept as a safe fallback.
const enabledCampaignSpend = rawResults.reduce((sum, row) =>
  sum + Number(row.metrics?.costMicros || 0) / 1_000_000, 0);
// True account MTD spend across ALL statuses (enabled + paused + removed).
// Uses .all() — Account Spend is a SIBLING branch off Edit Fields, so .item
// cannot resolve paired lineage and throws. Matched explicitly on customer ID
// so item order can never misattribute spend to the wrong account.
// CRITICAL: on any failure, fall back to the enabled sum — NEVER 0. A false 0
// reads as massive underpace and can trigger an auto-increase (Rule 3).
let accountTotalSpend = enabledCampaignSpend;
let spendSource = 'FALLBACK_NO_MATCH';
try {
  const spendItems = $('Account Spend (all statuses)').all();
  for (const it of spendItems) {
    const rows = (it.json && it.json.results) || [];
    const match = rows.find(row =>
      String(row.customer?.resourceName || '').split('/')[1] === adsIdForSpend
    );
    if (match) {
      accountTotalSpend = Number(match.metrics?.costMicros || 0) / 1_000_000;
      spendSource = 'ACCOUNT_TOTAL';
      break;
    }
  }
} catch (e) {
  spendSource = 'FALLBACK_REFERENCE_FAILED';
}
const totalActualSpend = accountTotalSpend;

// ============================================================================
// === PHASE 4 — CAMPAIGN-LEVEL BUDGET CONFIG + ELIGIBILITY GATE ============
// ----------------------------------------------------------------------------
// Reads the operator-set Campaign Budgets config (executeOnce) and decides,
// for THIS account, whether it is eligible for campaign-level steering.
//
// north star: reduce complexity + keep operator control. `budget_dollars`
// is READ-ONLY input — never written back. The only thing the agent ever
// mutates is the Google Ads daily budget (as it already does today).
//
// XOR: an account either steers per-campaign OR at account level, never both.
// Any budget mismatch (coverage incomplete / shared budget / drift /
// campaign-target sum overshoots the account budget) → fall back to
// account-level pacing and record a status_reason. Single fallback path,
// no rescaling, no exceptions.
// ============================================================================
let campaignBudgetConfig = [];
try {
  // executeOnce node upstream of this one; reads the whole Campaign Budgets tab.
  campaignBudgetConfig = $('Read Budget Config (Pacing)').all().map(i => i.json);
} catch (e) {
  campaignBudgetConfig = []; // config read unavailable → treat as account-level
}

const adsIdStr = String(adsId || '').trim();

// Build a per-campaign config map scoped to THIS account.
const configByCampaign = {};
let accountHasManagedIntent = false;
for (const r of campaignBudgetConfig) {
  if (!r || r.campaign_id == null || String(r.campaign_id).trim() === '') continue;
  // Tombstoned config row (campaign removed in Google Ads). Skip entirely so it
  // never enters configByCampaign / configuredCampaignIds and never trips the
  // Phase 4 drift check. Missing/blank `active` is treated as TRUE so pre-migration
  // rows and any hand-added row keep working.
  if (String(r.active != null ? r.active : 'TRUE').toUpperCase() === 'FALSE') continue;
  const rowAcct = r.google_ads_id != null ? String(r.google_ads_id).trim() : '';
  if (rowAcct !== adsIdStr) continue; // only this account's rows
  const managed = r.managed === true || String(r.managed).toUpperCase() === 'TRUE';
  configByCampaign[String(r.campaign_id)] = {
    budget_dollars: Number(r.budget_dollars) || 0,
    managed
  };
  if (managed) accountHasManagedIntent = true;
}

// === SHARED BUDGET DETECTION ===
// Build a map of budgetResource -> [campaignIds] to detect shared budgets.
// When multiple campaigns share a budget resource, amountMicros is the FULL
// shared amount on each row. Without dedup, we double/triple-count the
// account-level daily budget, which breaks severity math and utilization.
const budgetResourceMap = {};
rawResults.forEach(row => {
  const resource = row.campaignBudget?.resourceName;
  const campaignId = row.campaign?.id;
  if (resource) {
    if (!budgetResourceMap[resource]) {
      budgetResourceMap[resource] = {
        amountMicros: Number(row.campaignBudget?.amountMicros || 0),
        campaignIds: []
      };
    }
    budgetResourceMap[resource].campaignIds.push(campaignId);
  }
});
// Deduplicated account-level daily budget: count each budget resource only once
const totalDailyBudget = Object.values(budgetResourceMap).reduce((sum, entry) =>
  sum + entry.amountMicros / 1_000_000, 0);
const accountMonthlyBudget = hubspotMonthlyBudget > 0
  ? hubspotMonthlyBudget
  : totalDailyBudget * daysInMonth;
const accountExpectedSpend = accountMonthlyBudget * expectedPaceRatio;
const accountVariancePercent = accountExpectedSpend > 0
  ? Math.round(((totalActualSpend - accountExpectedSpend) / accountExpectedSpend) * 100)
  : 0;
// === CAMPAIGN-LEVEL BUDGET ALLOCATION ===
const remainingBudget = accountMonthlyBudget - totalActualSpend;
const proposedDailyBudget = Math.max(0, Math.round(remainingBudget / daysRemaining));

// ============================================================================
// === PHASE 4 — ELIGIBILITY EVALUATION (per account, runs before targets) ===
// Mirrors the checks already written in `Compute Status`, applied inline so
// effective_mode is known BEFORE per-campaign targets are computed (Option A).
// ============================================================================
let campaignSteeringEligible = false;
let campaignSteeringReason = 'good';       // good | not_managed | incomplete | shared_budget | drift | sum_overshoot
const enabledCampaignIds = rawResults
  .map(row => row.campaign?.id)
  .filter(id => id != null)
  .map(String);
const configuredCampaignIds = Object.keys(configByCampaign);

// PHASE 5: per-campaign drift attribution map (only meaningful for managed accounts)
let perCampaignReason = {};

if (!accountHasManagedIntent) {
  campaignSteeringReason = 'not_managed';
} else {
  // 1) Coverage: every ENABLED campaign in the feed must have a config row.
  //    (Feed is filtered WHERE campaign.status='ENABLED', so it IS the enabled set.)
  const uncovered = enabledCampaignIds.filter(id => !configByCampaign[id]);
  // 2) Shared budget: any enabled campaign on a shared Google Ads budget → can't steer.
  const hasSharedBudget = rawResults.some(row => {
    const resource = row.campaignBudget?.resourceName;
    return resource && budgetResourceMap[resource].campaignIds.length > 1;
  });
  // 3) Drift: a configured campaign no longer exists in the enabled set.
  const enabledSet = new Set(enabledCampaignIds);
  const drift = configuredCampaignIds.some(id => !enabledSet.has(id));
  // 4) Sum overshoot: operator monthly targets sum above the account budget.
  const configuredMonthlyTotal = configuredCampaignIds
    .reduce((s, id) => s + (configByCampaign[id].budget_dollars || 0), 0);
  const sumOvershoot = accountMonthlyBudget > 0
    && configuredMonthlyTotal > accountMonthlyBudget;

  // ===== PHASE 5 — PER-CAMPAIGN DRIFT ATTRIBUTION =====
  // Reason for EACH configured campaign, so the portal can point at the offender
  // instead of stamping the same account-level reason on every row.
  const sharedIdsP5 = new Set(
    rawResults
      .filter(row => {
        const res = row.campaignBudget?.resourceName;
        return res && budgetResourceMap[res].campaignIds.length > 1;
      })
      .map(row => row.campaign?.id != null ? String(row.campaign.id) : '')
      .filter(Boolean)
  );
  for (const cid of configuredCampaignIds) {
    if (!enabledSet.has(cid))       perCampaignReason[cid] = 'drift';         // configured, not live
    else if (sharedIdsP5.has(cid))  perCampaignReason[cid] = 'shared_budget'; // on a shared budget
    else                            perCampaignReason[cid] = 'ok';            // this one is fine
  }

  if (uncovered.length > 0)      campaignSteeringReason = 'incomplete';
  else if (hasSharedBudget)      campaignSteeringReason = 'shared_budget';
  else if (drift)                campaignSteeringReason = 'drift';
  else if (sumOvershoot)         campaignSteeringReason = 'sum_overshoot';
  else {
    campaignSteeringEligible = true;
    campaignSteeringReason = 'good';
  }
}

// === DAY-OF-WEEK ADJUSTMENT (account-level; applied per campaign at the
//     FINAL step in Merged Data — proposedDailyBudget stays the BASE) ===
const normalDailyAverage = daysInMonth > 0 ? accountMonthlyBudget / daysInMonth : 0;
const rawDowAdjustment = DOW_MULTIPLIERS[today.getDay()] || 0;
const dowFlags = [];
let dowAdjustment = rawDowAdjustment;
// Bill's end-of-month catch-up rule + symmetric overspend guard:
// if the required daily pace is far from the normal daily average
// (>130% behind or <70% ahead), halve the multiplier deviation today.
const catchUpActive = normalDailyAverage > 0 && (
  proposedDailyBudget > 1.3 * normalDailyAverage ||
  proposedDailyBudget < 0.7 * normalDailyAverage
);
if (catchUpActive) {
  dowAdjustment = dowAdjustment * 0.5;
  dowFlags.push('CATCH_UP_HALVED');
}
// Month-end guard: with <=2 days left there is no tomorrow for the
// remaining-budget feedback loop to self-correct — suppress DOW entirely.
if (daysRemaining <= 2) {
  dowAdjustment = 0;
  dowFlags.push('MONTH_END_SUPPRESSED');
}
const dowMultiplier = Math.round((1 + dowAdjustment) * 100) / 100;
// === ESTIMATED YESTERDAY MULTIPLIER (base de-normalization) ===
// The live budget read from the API this morning embodies YESTERDAY's
// multiplier. All comparisons must run base-to-base, so divide it out.
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayISO = yesterday.toISOString().split('T')[0];
let estimatedYesterdayMultiplier = 1;
if (yesterdayISO >= DOW_ENABLED_SINCE) {
  estimatedYesterdayMultiplier = 1 + (DOW_MULTIPLIERS[yesterday.getDay()] || 0);
}
// Yesterday was month-end suppressed (its daysRemaining was <= 2), or was
// the day-1 grace period (no mutate ran) — live budget carries no multiplier.
if (daysRemaining <= 1 || dayOfMonth <= 2) {
  estimatedYesterdayMultiplier = 1;
}
const campaigns = rawResults.map(row => {
  const rawDailyBudget = Number(row.campaignBudget?.amountMicros || 0) / 1_000_000;
  const budgetResource = row.campaignBudget?.resourceName;
  const siblingCount = budgetResource
    ? budgetResourceMap[budgetResource].campaignIds.length
    : 1;
  const isSharedBudget = siblingCount > 1;
  // effectiveDailyBudget = this campaign's proportional share of the budget resource
  const effectiveDailyBudget = Math.round(rawDailyBudget / siblingCount);
  // De-normalized base view of the live budget (strip yesterday's multiplier)
  const baseCurrentDailyBudget = estimatedYesterdayMultiplier !== 0
    ? Math.round(effectiveDailyBudget / estimatedYesterdayMultiplier)
    : effectiveDailyBudget;
  const actualSpend = Number(row.metrics?.costMicros || 0) / 1_000_000;
  // Use total account spend for pacing, but distribute the remaining
  // allowance only across campaigns that are currently enabled.
  const spendFraction = enabledCampaignSpend > 0
    ? actualSpend / enabledCampaignSpend
    : 1 / Math.max(rawResults.length, 1);

  const spendShare = Math.round(spendFraction * 100);

  const campaignId = row.campaign?.id != null ? String(row.campaign?.id) : null;

  // ===== PHASE 4 — PER-CAMPAIGN TARGET SELECTION =====
  // Managed + eligible → pace this campaign toward ITS OWN monthly target
  // using the same remaining/days-remaining formula the account uses.
  // Otherwise → the existing account-spend-share split (unchanged behavior).
  const cfg = campaignId ? configByCampaign[campaignId] : null;
  let campaignProposedBudget;
  let campaignSteered = false;
  if (campaignSteeringEligible && cfg && cfg.managed) {
    const campaignMonthlyTarget = cfg.budget_dollars || 0;
    const campaignRemaining = campaignMonthlyTarget - actualSpend;
    campaignProposedBudget = Math.max(0, Math.round(campaignRemaining / daysRemaining));
    campaignSteered = true;
  } else {
      campaignProposedBudget = Math.round(proposedDailyBudget * spendFraction);
    }

  return {
    campaignId: row.campaign?.id,
    campaignStatus: row.campaign?.status || null,
    campaignBudgetResource: budgetResource,
    name: row.campaign?.name || 'Unknown campaign',
    actualSpend: Math.round(actualSpend),
    currentDailyBudget: effectiveDailyBudget,
    baseCurrentDailyBudget,
    rawBudgetResourceAmount: Math.round(rawDailyBudget),
    proposedDailyBudget: campaignProposedBudget,
    searchBudgetLostIS: Number(row.metrics?.searchBudgetLostImpressionShare || 0),
    spendShare,
    isSharedBudget,
    sharedBudgetSiblings: siblingCount,
    // Phase 4 audit fields
    campaignSteered,
    campaignMonthlyTarget: (cfg && cfg.managed) ? (cfg.budget_dollars || 0) : null
  };
});
// === TASK 1 (2026-07-23): DROP DEAD/TEST CAMPAIGNS (zero MTD spend) ===
// Enabled campaigns that have spent $0 month-to-date are treated as inactive/test
// campaigns and excluded from pacing routing, logging, and the portal. Gated to
// dayOfMonth > 1 so the 1st of a new month (all spend naturally $0) does not wipe
// every campaign — that is the existing day-1 grace period.
const activeCampaigns = dayOfMonth > 1
  ? campaigns.filter(c => c.actualSpend > 0)
  : campaigns;

// === PROJECTION-BASED SEVERITY MODEL ===
const dailyRunRate = dayOfMonth > 0 ? totalActualSpend / dayOfMonth : 0;
const projectedTotal = totalActualSpend + (dailyRunRate * daysRemaining);
const projectedOvershoot = projectedTotal - accountMonthlyBudget;
const dailyCorrectionNeeded = daysRemaining > 0
  ? projectedOvershoot / daysRemaining
  : projectedOvershoot;
const currentAccountDailyBudget = totalDailyBudget > 0 ? totalDailyBudget : 1;
const correctionPercent = Math.abs(dailyCorrectionNeeded) / currentAccountDailyBudget;
const direction = projectedOvershoot > 0 ? 'over' : 'under';
let severity;
if (correctionPercent < 0.05) {
  severity = 'OK';
} else if (direction === 'over' && correctionPercent >= 0.30) {
  severity = 'CRITICAL';
} else if (direction === 'over' && correctionPercent >= 0.15) {
  severity = 'ALERT';
} else if (direction === 'over') {
  severity = 'AUTO';
} else if (direction === 'under' && correctionPercent >= 0.15) {
  severity = 'UNDERPACE';
} else {
  severity = 'AUTO';
}
// === CLIENT-FACING DISPLAY STATUS (5 symmetric tiers) ===
// Basis: how far the account is over/under its pace vs the daily target
// (= month-to-date variance %, the figure shown on the account). Decoupled
// from routing `severity` — display only, drives NO money decision.
// Bands (">" = higher tier): |var| <= 10% On Track; 10-20% Under/Overpacing
// (20% stays mild); > 20% Significantly. + = over target, - = under.
const displayVariance = accountVariancePercent;      // signed integer %, + over / - under
const displayVarianceMag = Math.abs(displayVariance);
let displayStatus;
if (displayVarianceMag <= 10) {
  displayStatus = 'On Track';
} else if (displayVariance > 0) {
  displayStatus = displayVarianceMag > 20 ? 'Significantly Overpacing' : 'Overpacing';
} else {
  displayStatus = displayVarianceMag > 20 ? 'Significantly Underpacing' : 'Underpacing';
}
// Damping caps by severity
const dampingCaps = {
  CRITICAL: 0.30,
  ALERT: 0.20,
  AUTO: 0.10,
  UNDERPACE: 0.20,
  OK: 0.05
};
const maxChangePercent = dampingCaps[severity] || 0.10;
function dampAdjustment(currentBudget, rawProposed, cap) {
  if (currentBudget === 0) return rawProposed;
  const ceiling = currentBudget * (1 + cap);
  const floor = currentBudget * (1 - cap);
  return Math.round(Math.min(ceiling, Math.max(floor, rawProposed)));
}
// DAMPING NOW CLAMPS AGAINST THE DE-NORMALIZED BASE-CURRENT, not the
// live (multiplied) budget — otherwise yesterday's multiplier corrupts
// today's base and the DOW swing gets eaten by the damping cap.
const dampedCampaigns = activeCampaigns.map(c => {
  const dampedBudget = dampAdjustment(c.baseCurrentDailyBudget, c.proposedDailyBudget, maxChangePercent);
  return {
    ...c,
    rawProposedDailyBudget: c.proposedDailyBudget,
    proposedDailyBudget: dampedBudget,
    dampedFrom: c.proposedDailyBudget !== dampedBudget ? c.proposedDailyBudget : null
  };
});
return {
  json: {
    practiceName,
    adsId,
    severity,
    displayStatus,   // client-facing 5-tier pacing label (display only, not routing)
    date: todayISO,
    // Phase 4: account-level steering mode (drives XOR + portal status)
    campaignSteering: {
      eligible: campaignSteeringEligible,
      effectiveMode: campaignSteeringEligible ? 'campaign' : 'account',
      statusReason: campaignSteeringReason,
      managedIntent: accountHasManagedIntent,
      configuredCount: configuredCampaignIds.length,
      enabledCount: enabledCampaignIds.length,
      perCampaignReason   // PHASE 5: { campaign_id: 'drift'|'shared_budget'|'ok' }
    },
    pacing: {
      monthlyBudget: Math.round(accountMonthlyBudget),
      totalActualSpend: Math.round(totalActualSpend),
      expectedSpend: Math.round(accountExpectedSpend),
      variancePercent: accountVariancePercent,
      remainingBudget: Math.round(remainingBudget),
      currentDailyBudget: Math.round(totalDailyBudget),
      proposedDailyBudget,
      flagged: severity !== 'OK',
      spendSource,
      enabledCampaignSpend: Math.round(enabledCampaignSpend)
    },
    projection: {
      dailyRunRate: Math.round(dailyRunRate),
      projectedTotal: Math.round(projectedTotal),
      projectedOvershoot: Math.round(projectedOvershoot),
      dailyCorrectionNeeded: Math.round(dailyCorrectionNeeded),
      correctionPercent: Math.round(correctionPercent * 100),
      direction,
      maxChangePercent: Math.round(maxChangePercent * 100)
    },
    dateContext: {
      dayOfMonth,
      daysInMonth,
      daysRemaining,
      expectedPacePercent: Math.round(expectedPaceRatio * 100)
    },
    dow: {
      multiplier: dowMultiplier,
      rawAdjustment: rawDowAdjustment,
      catchUpActive,
      flags: dowFlags,
      estimatedYesterdayMultiplier,
      normalDailyAverage: Math.round(normalDailyAverage)
    },
    campaigns: dampedCampaigns
  }
};

const account = $input.item.json;

// Yesterday data — campaign-level if available, account-level as fallback
const yesterdayAccountBudget = Number(account.yesterdays_account_proposed_daily_budget) || 0;
const yesterdayCampaigns = account.yesterdays_campaigns || {};

// 7-day spend data from API
const sevenDayCampaigns = account.sevenDayCampaigns || [];

// === BUILD 7-DAY UTILIZATION MAP ===
// Structure: { campaignId: [{ date, spend, budget, utilization }, ...] }
const utilizationMap = {};

for (const row of sevenDayCampaigns) {
  const cId = String(row.campaign_id);
  if (!utilizationMap[cId]) {
    utilizationMap[cId] = [];
  }
  const spend = Number(row.cost_micros || 0) / 1_000_000;
  const budget = Number(row.budget_micros || 0) / 1_000_000;
  const utilization = budget > 0 ? spend / budget : 0;
  utilizationMap[cId].push({
    date: row.date,
    spend,
    budget,
    utilization
  });
}

// Determine chronic demand-limited status per campaign
// Rule: < 70% utilization for ALL of the last 7 days
function isChronicDemandLimited(campaignId) {
  const days = utilizationMap[String(campaignId)] || [];
  if (days.length < 7) return false; // not enough data to judge
  return days.every(d => d.utilization < 0.70);
}

// Get yesterday's utilization from the 7-day data
function getYesterdayUtilization(campaignId) {
  const days = utilizationMap[String(campaignId)] || [];
  if (days.length === 0) return null;
  // Sort by date descending, take the most recent
  const sorted = [...days].sort((a, b) => b.date.localeCompare(a.date));
  return sorted[0]; // most recent day in the 7-day window
}
// Get 7-day utilization
function getSevenDayAvgUtilization(campaignId) {
  const days = utilizationMap[String(campaignId)] || [];
  if (days.length === 0) return null;
  const totalUtil = days.reduce((sum, d) => sum + d.utilization, 0);
  return Math.round((totalUtil / days.length) * 100);
}

// === DAY-1-OF-MONTH GRACE PERIOD ===
// On the 1st, $0 spend makes every account look UNDERPACE/CRITICAL.
// Skip all classification and recommendation logic — just log and move on.
if (account.dateContext.dayOfMonth <= 1) {
  const graceCampaigns = (account.campaigns || []).map(c => {
    const cId = String(c.campaignId);
    return {
      ...c,
      isBudgetLimited: false,
      isChronicDemandLimited: false,
      classification: null,
      budgetLostIS: 0,
      yesterdayUtilization: null,
      sevenDayAvgUtilization: getSevenDayAvgUtilization(cId),
      utilizationDays: (utilizationMap[cId] || []).length,
      practiceName: account.practiceName,
      adsId: account.adsId,
      yesterdayAccountBudget,
      yesterdayCampaignBudget: 0,
      campaignProposedMultiple: null,
      accountProposedMultiple: null,
      variancePercent: account.pacing.variancePercent,
      correctionPercent: account.projection.correctionPercent,
      conflictsWithPacing: false,
      recommendationType: 'NO_CHANGE',
      skipReason: 'MONTH_START_GRACE',
      dowMultiplier: 1,
      dowFlags: 'MONTH_START_GRACE',
      finalDailyBudget: c.proposedDailyBudget
    };
  });

  return {
    json: {
      practiceName: account.practiceName,
      adsId: account.adsId,
      severity: 'OK',
      displayStatus: 'On Track',   // grace period: force On Track (spend is $0 on the 1st)
      date: account.date,
      pacing: account.pacing,
      projection: account.projection,
      dateContext: account.dateContext,
      dow: account.dow,
      accountOnTrack: true,
      allDemandLimited: false,
      anyBudgetLimited: false,
      skipReason: 'MONTH_START_GRACE',
      campaignSteering: account.campaignSteering || {
        eligible: false, effectiveMode: 'account', statusReason: 'not_managed'
      },
      actions: {
        autoApply: [],
        needsApproval: [],
        pauseList: [],
        log: graceCampaigns
      },
      summary: { autoApplyCount: 0, approvalCount: 0, pauseCount: 0 }
    }
  };
}

// === ACCOUNT-LEVEL PACING OVERRIDE (Bill's Rule 4) ===
// If 95-105% pace MTD, don't touch any budgets
const accountPacePercent = account.pacing.expectedSpend > 0
  ? (account.pacing.totalActualSpend / account.pacing.expectedSpend) * 100
  : 100;
const accountOnTrack = accountPacePercent >= 95 && accountPacePercent <= 105;

// === CLASSIFY EACH CAMPAIGN ===
const classifiedCampaigns = account.campaigns.map(c => {
  const cId = String(c.campaignId);

  // Budget-limited signals (Bill's Rule 1)
  const budgetLostIS = c.searchBudgetLostIS || 0;
  const yesterdayUtil = getYesterdayUtilization(cId);
  const yesterdayUtilPercent = yesterdayUtil ? yesterdayUtil.utilization : 0;

  const sevenDayUtil = getSevenDayAvgUtilization(cId);
  const isBudgetLimited = budgetLostIS > 0.05 
    || yesterdayUtilPercent >= 0.95
    || (sevenDayUtil !== null && sevenDayUtil >= 95);
  const chronicDemandLimited = isChronicDemandLimited(cId);

  return {
    ...c,
    isBudgetLimited,
    isChronicDemandLimited: chronicDemandLimited,
    classification: isBudgetLimited ? 'BUDGET_LIMITED' : 'DEMAND_LIMITED',
    budgetLostIS: Math.round(budgetLostIS * 100) / 100,
    yesterdayUtilization: yesterdayUtil
      ? Math.round(yesterdayUtil.utilization * 100)
      : null,
    sevenDayAvgUtilization: getSevenDayAvgUtilization(cId),
    utilizationDays: (utilizationMap[cId] || []).length
  };
});

const anyBudgetLimited = classifiedCampaigns.some(c => c.isBudgetLimited);
const allDemandLimited = classifiedCampaigns.every(c => !c.isBudgetLimited);

// === PHASE 4 — CAMPAIGN STEERING XOR (full bypass) ===
// When an account is managed + eligible, campaign-level steering is the ONLY
// mutation path. The account-level severity gates (Rule 4 on-track freeze,
// Rule 2 demand-side INVESTIGATE) and account-direction routing are bypassed;
// each campaign routes purely on its own target-vs-current delta. Account
// correctionPercent/severity remain computed for display only.

// === TASK 2 (2026-07-23): ACCOUNT BUDGET-CAP PAUSE ===
// MTD spend has reached/exceeded the monthly budget → hard-stop the whole account:
// every enabled campaign routes to PAUSE_CAMPAIGN, regardless of severity or
// campaign-steering. (Day-1 grace handled above.)
const capReached =
  Number(account.pacing.monthlyBudget) > 0 &&
  Number(account.pacing.totalActualSpend) >= Number(account.pacing.monthlyBudget);
const campaignSteeringEligible = !!(account.campaignSteering && account.campaignSteering.eligible);

// === DETERMINE EFFECTIVE SEVERITY ===
let effectiveSeverity = account.severity;
let skipReason = null;

if (!campaignSteeringEligible) {
  if (accountOnTrack) {
    // Rule 4: Account on track — no changes
    effectiveSeverity = 'OK';
    skipReason = 'ACCOUNT_ON_TRACK';
  } else if (account.projection.direction === 'under' && allDemandLimited) {
    // Rule 2: Underpacing but no campaign is budget-limited
    effectiveSeverity = 'INVESTIGATE';
    skipReason = 'DEMAND_SIDE_ISSUE';
  }
}

// === BUILD ACTIONS ===
const actions = {
  autoApply: [],
  needsApproval: [],
  pauseList: [],
  log: []
};

// Account-level multiple — kept for logging only
const todayProposed = account.pacing.proposedDailyBudget;
const accountProposedMultiple = yesterdayAccountBudget > 0
  ? todayProposed / yesterdayAccountBudget
  : null;

classifiedCampaigns.forEach(c => {
  const cId = String(c.campaignId);
  const yesterdayCampaign = yesterdayCampaigns[cId] || null;
  const yesterdayCampaignBudget = yesterdayCampaign
    ? yesterdayCampaign.proposedDailyBudget
    : 0;

  // All change/direction comparisons run against the DE-NORMALIZED base
  // view of the live budget. The raw live budget embodies yesterday's
  // DOW multiplier; comparing the base proposal against it would make
  // intended DOW swings look like pacing changes.
  const compareBudget = (c.baseCurrentDailyBudget != null)
    ? c.baseCurrentDailyBudget
    : c.currentDailyBudget;

  // Per-campaign escalation check (yesterday's logged budget is already a base)
  const campaignProposedMultiple = yesterdayCampaignBudget > 0
    ? c.proposedDailyBudget / yesterdayCampaignBudget
    : null;
  const campaignExceedsEscalation = campaignProposedMultiple !== null
    && (campaignProposedMultiple >= 2 || campaignProposedMultiple <= 0.5);

  // Meaningful change check
  const dollarChange = Math.abs(c.proposedDailyBudget - compareBudget);
  const percentChange = compareBudget > 0
    ? Math.abs((c.proposedDailyBudget / compareBudget) - 1)
    : (c.proposedDailyBudget > 0 ? 1 : 0);
  const meaningfulChange = percentChange >= 0.10 || dollarChange >= 3;

  // Direction consistency check
  // PHASE 4: for steered campaigns this account-direction conflict concept
  // does not apply — each campaign moves toward its own target. Force false.
  const accountDirection = account.projection.direction;
  const campaignDirection = c.proposedDailyBudget > compareBudget ? 'increase' : 'decrease';
  const conflictsWithPacing = !campaignSteeringEligible && meaningfulChange && (
    (accountDirection === 'over' && campaignDirection === 'increase') ||
    (accountDirection === 'under' && campaignDirection === 'decrease')
  );

  let recommendationType;
  let campaignSkipReason = skipReason; // inherit account-level skip if set

  if (capReached) {
    // Account cap hit — hard stop this campaign.
    recommendationType = 'PAUSE_CAMPAIGN';
    campaignSkipReason = 'BUDGET_CAP_REACHED';
  } else if (campaignSteeringEligible) {
    // === PHASE 4 — CAMPAIGN-STEERED ROUTING ===
    // Route on this campaign's own target-vs-current delta. Meaningful moves
    // go to AUTO increase/decrease; the 2x escalation safety net still forces
    // approval. Damping (upstream) already caps the per-day step size, and the
    // auto-decrease promotion + shared-budget grouping below still apply.
    if (!meaningfulChange) {
      recommendationType = 'NO_CHANGE';
      campaignSkipReason = 'NO_MEANINGFUL_CHANGE';
    } else if (campaignExceedsEscalation) {
      recommendationType = campaignDirection === 'increase'
        ? 'BUDGET_INCREASE_APPROVAL'
        : 'BUDGET_DECREASE_APPROVAL';
    } else {
      recommendationType = campaignDirection === 'increase'
        ? 'BUDGET_INCREASE'
        : 'BUDGET_DECREASE';
    }

  } else if (skipReason === 'ACCOUNT_ON_TRACK') {
    // Rule 4: Account on track — no PACING changes for anyone.
    // (Day-of-week shaping is applied later, in the DOW final transform.)
    recommendationType = 'NO_CHANGE';
    campaignSkipReason = 'ACCOUNT_ON_TRACK';

  } else if (skipReason === 'DEMAND_SIDE_ISSUE') {
    // Rule 2: All demand-limited — no budget changes
    recommendationType = 'NO_CHANGE';
    campaignSkipReason = 'DEMAND_SIDE_ISSUE';

  } else if (account.projection.direction === 'under' && !c.isBudgetLimited && !c.isChronicDemandLimited) {
    // Rule 3 (partial): Underpacing, this campaign is demand-limited but NOT chronic — leave alone
    recommendationType = 'NO_CHANGE';
    campaignSkipReason = 'DEMAND_LIMITED_NO_CHANGE';

  } else if (account.projection.direction === 'under' && !c.isBudgetLimited && c.isChronicDemandLimited) {
    // Rule 3 (partial): Chronic demand-limited sibling — eligible donor
    // Only donate if there ARE budget-limited siblings that need it
    if (anyBudgetLimited && meaningfulChange) {
      recommendationType = 'BUDGET_DECREASE_APPROVAL';
      campaignSkipReason = 'CHRONIC_DEMAND_LIMITED_DONOR';
    } else {
      recommendationType = 'NO_CHANGE';
      campaignSkipReason = 'CHRONIC_BUT_NO_BUDGET_LIMITED_SIBLING';
    }

  } else if (account.projection.direction === 'under' && c.isBudgetLimited) {
    // Rule 3 (core): Budget-limited campaign on an underpacing account — INCREASE
    if (meaningfulChange) {
      recommendationType = 'BUDGET_INCREASE';
      campaignSkipReason = null;
    } else {
      recommendationType = 'NO_CHANGE';
      campaignSkipReason = 'BUDGET_LIMITED_BUT_CHANGE_TOO_SMALL';
    }

  } else if (effectiveSeverity === 'CRITICAL' && meaningfulChange) {
    // Overpacing: CRITICAL — aggressive action
    recommendationType = c.proposedDailyBudget === 0
      ? 'PAUSE_CAMPAIGN'
      : (c.proposedDailyBudget > compareBudget
          ? 'BUDGET_INCREASE_APPROVAL'
          : 'BUDGET_DECREASE_APPROVAL');

  } else if (conflictsWithPacing) {
    // Direction conflict — force to approval
    recommendationType = campaignDirection === 'increase'
      ? 'BUDGET_INCREASE_APPROVAL'
      : 'BUDGET_DECREASE_APPROVAL';

  } else if (campaignExceedsEscalation) {
    // 2x escalation safety net
    recommendationType = c.proposedDailyBudget > compareBudget
      ? 'BUDGET_INCREASE_APPROVAL'
      : 'BUDGET_DECREASE_APPROVAL';

  } else if (effectiveSeverity === 'ALERT' && meaningfulChange) {
    // ALERT: meaningful changes need approval
    recommendationType = c.proposedDailyBudget > compareBudget
      ? 'BUDGET_INCREASE_APPROVAL'
      : 'BUDGET_DECREASE_APPROVAL';

  } else if ((effectiveSeverity === 'AUTO' || effectiveSeverity === 'UNDERPACE') && meaningfulChange) {
    // AUTO/UNDERPACE with budget-limited campaigns already handled above
    // This catches overpacing AUTO scenarios
    recommendationType = c.proposedDailyBudget > compareBudget
      ? 'BUDGET_INCREASE'
      : 'BUDGET_DECREASE';

  } else {
    recommendationType = 'NO_CHANGE';
  }

  // Bill's Rule 3: Never cut a budget-limited campaign on an underpacing account.
  // PHASE 4: this is an account-direction rule; it does not apply under campaign
  // steering, where a campaign over its OWN target should be cut regardless.
  if (!campaignSteeringEligible
      && c.isBudgetLimited
      && account.projection.direction === 'under'
      && recommendationType !== 'NO_CHANGE'
      && c.proposedDailyBudget < compareBudget) {
    recommendationType = 'NO_CHANGE';
    campaignSkipReason = 'BUDGET_LIMITED_NO_DECREASE';
  }

  // Catch-all: ensure every NO_CHANGE has a skip reason
  if (recommendationType === 'NO_CHANGE' && !campaignSkipReason) {
    campaignSkipReason = 'NO_MEANINGFUL_CHANGE';
  }

  // Reconcile label with actual dollar direction (base vs base)
  if (recommendationType === 'BUDGET_INCREASE' && c.proposedDailyBudget < compareBudget) {
    recommendationType = 'BUDGET_DECREASE';
  } else if (recommendationType === 'BUDGET_DECREASE' && c.proposedDailyBudget > compareBudget) {
    recommendationType = 'BUDGET_INCREASE';
  } else if (recommendationType === 'BUDGET_INCREASE_APPROVAL' && c.proposedDailyBudget < compareBudget) {
    recommendationType = 'BUDGET_DECREASE_APPROVAL';
  } else if (recommendationType === 'BUDGET_DECREASE_APPROVAL' && c.proposedDailyBudget > compareBudget) {
    recommendationType = 'BUDGET_INCREASE_APPROVAL';
  }

  // If proposed equals base-current, it's NO_CHANGE regardless
  if (c.proposedDailyBudget === compareBudget) {
    recommendationType = 'NO_CHANGE';
    if (!campaignSkipReason) campaignSkipReason = 'NO_MEANINGFUL_CHANGE';
  }

  // === BILL'S AUTO-DECREASE RULE (June 2026) ===
  // Decreases with an applied cut of ≤30% auto-apply instead of routing to approval.
  // Upstream damping already caps single-day cuts (CRITICAL ±30%, ALERT ±20%),
  // so this promotes most CRITICAL/ALERT decrease approvals to auto-apply.
  // Safety flags still force approval: direction conflicts, 2x escalation,
  // and chronic demand-limited donor cuts (Rule 3 reallocations).
  // DOW NOTE: measured against the DE-NORMALIZED base (compareBudget), not the
  // live budget — otherwise yesterday's multiplier distorts the ≤30% test.
  const appliedDecreasePercent = (compareBudget > 0 && c.proposedDailyBudget < compareBudget)
    ? (compareBudget - c.proposedDailyBudget) / compareBudget
    : 0;

  let autoDecreasePromoted = false;

  // Promote when the cut is no deeper than the rounded 30% damping floor.
  // Comparing dollars (not percent) avoids rounding artifacts on small budgets —
  // e.g., $42 × 0.70 = $29.40 rounds to $29, a 30.95% cut that a strict
  // percent check would wrongly reject.
  const thirtyPercentFloor = Math.round(compareBudget * 0.70);

  if (recommendationType === 'BUDGET_DECREASE_APPROVAL'
      && appliedDecreasePercent > 0
      && c.proposedDailyBudget >= thirtyPercentFloor
      && !conflictsWithPacing
      && !campaignExceedsEscalation
      && campaignSkipReason !== 'CHRONIC_DEMAND_LIMITED_DONOR') {
    recommendationType = 'BUDGET_DECREASE';
    autoDecreasePromoted = true;
  }

  const campaignAction = {
    ...c,
    practiceName: account.practiceName,
    adsId: account.adsId,
    yesterdayAccountBudget,
    yesterdayCampaignBudget,
    campaignProposedMultiple: campaignProposedMultiple !== null
      ? Math.round(campaignProposedMultiple * 100) / 100
      : null,
    accountProposedMultiple: accountProposedMultiple !== null
      ? Math.round(accountProposedMultiple * 100) / 100
      : null,
    variancePercent: account.pacing.variancePercent,
    correctionPercent: account.projection.correctionPercent,
    conflictsWithPacing,
    appliedDecreasePercent: Math.round(appliedDecreasePercent * 100),
    autoDecreasePromoted,
    recommendationType,
    skipReason: campaignSkipReason,
    pauseReason: recommendationType === 'PAUSE_CAMPAIGN'
      ? (campaignSkipReason === 'BUDGET_CAP_REACHED' ? 'BUDGET_CAP_REACHED' : 'MONTH_END_ZERO')
      : null
  };

  // Route to action buckets
  if (recommendationType === 'PAUSE_CAMPAIGN') {
    actions.pauseList.push(campaignAction);
  } else if (recommendationType.includes('APPROVAL')) {
    actions.needsApproval.push(campaignAction);
  } else if (recommendationType === 'BUDGET_INCREASE' || recommendationType === 'BUDGET_DECREASE') {
    actions.autoApply.push(campaignAction);
  }

  actions.log.push(campaignAction);
});

// === SHARED BUDGET RECOMMENDATION GROUPING ===
// Siblings sharing a budget resource must get the same recommendation.
// Run after all individual recommendations are set, before label reconciliation.

const budgetGroups = {};
actions.log.forEach((c, idx) => {
  if (c.isSharedBudget && c.campaignBudgetResource) {
    if (!budgetGroups[c.campaignBudgetResource]) {
      budgetGroups[c.campaignBudgetResource] = [];
    }
    budgetGroups[c.campaignBudgetResource].push(idx);
  }
});

for (const [resource, indices] of Object.entries(budgetGroups)) {
  if (indices.length < 2) continue;

  const siblings = indices.map(i => actions.log[i]);
  const recTypes = siblings.map(s => s.recommendationType);
  const directions = siblings.map(s => {
    if (s.recommendationType === 'NO_CHANGE') return 'none';
    const cmp = (s.baseCurrentDailyBudget != null) ? s.baseCurrentDailyBudget : s.currentDailyBudget;
    return s.proposedDailyBudget > cmp ? 'increase' : 'decrease';
  });

  const uniqueDirections = [...new Set(directions.filter(d => d !== 'none'))];
  const anyApproval = recTypes.some(r => r.includes('APPROVAL'));
  const anyPause = recTypes.some(r => r === 'PAUSE_CAMPAIGN');

  let groupRec;
  let groupNote;

  if (anyPause) {
    // If any sibling wants to pause, escalate the whole group to approval
    groupRec = 'BUDGET_DECREASE_APPROVAL';
    groupNote = 'Shared budget — sibling campaign flagged for pause, group routed to approval';
  } else if (uniqueDirections.length > 1) {
    // Conflicting directions — default to NO_CHANGE
    groupRec = 'NO_CHANGE';
    groupNote = 'Shared budget — sibling campaigns disagree on direction, no change applied';
  } else if (uniqueDirections.length === 1 && anyApproval) {
    // Same direction but at least one needs approval — whole group needs approval
    groupRec = uniqueDirections[0] === 'increase'
      ? 'BUDGET_INCREASE_APPROVAL'
      : 'BUDGET_DECREASE_APPROVAL';
    groupNote = 'Shared budget — grouped recommendation requires approval';
  } else if (uniqueDirections.length === 1) {
    // Same direction, all auto — keep it
    groupRec = uniqueDirections[0] === 'increase'
      ? 'BUDGET_INCREASE'
      : 'BUDGET_DECREASE';
    groupNote = 'Shared budget — siblings agree on direction';
  } else {
    // All NO_CHANGE already
    groupRec = 'NO_CHANGE';
    groupNote = 'Shared budget — no changes needed';
  }

  // Apply unified recommendation to all siblings
  for (const idx of indices) {
    const c = actions.log[idx];
    c.recommendationType = groupRec;
    c.sharedBudgetNote = groupNote;

    if (groupRec === 'NO_CHANGE' && !c.skipReason) {
      c.skipReason = 'SHARED_BUDGET_CONFLICT';
    }
  }
}

// === DAY-OF-WEEK FINAL TRANSFORM ===
// Applied LAST: after all pacing logic, damping, routing, and shared-budget
// grouping. proposedDailyBudget remains the BASE everywhere upstream and in
// the sheet; finalDailyBudget is the only value the mutate call may use.

const accountDow = account.dow || { multiplier: 1, flags: [] };
const dowM = accountDow.multiplier || 1;

// Rows that must never be converted to a DOW adjustment
const DOW_CONVERT_EXCLUSIONS = ['MONTH_START_GRACE', 'SHARED_BUDGET_CONFLICT'];

actions.log.forEach(c => {
  const isAction = ['BUDGET_INCREASE','BUDGET_DECREASE',
                    'BUDGET_INCREASE_APPROVAL','BUDGET_DECREASE_APPROVAL'].includes(c.recommendationType);
  const base = isAction
    ? c.proposedDailyBudget
    : ((c.baseCurrentDailyBudget != null) ? c.baseCurrentDailyBudget : c.currentDailyBudget);

  // Shape the base, then hard-clamp: never outside 0.55x–1.55x of base
  let final = Math.round(base * dowM);
  const ceiling = Math.round(base * 1.55);
  const floor = Math.round(base * 0.55);
  final = Math.min(ceiling, Math.max(floor, final));

  // Account-level safety guard:
  // On an overpacing account, DOW shaping must not turn a pacing reduction
  // into an increase above the budget currently live in Google Ads.
  // Campaign-steered accounts are excluded because each campaign follows
  // its own monthly target.
  const overpacingAccountGuard =
    !campaignSteeringEligible &&
    account.projection?.direction === 'over';

  if (overpacingAccountGuard && final > c.currentDailyBudget) {
    final = c.currentDailyBudget;
    c.dowGuardApplied = true;
  } else {
    c.dowGuardApplied = false;
  }

  c.dowMultiplier = dowM;
  c.dowFlags = (accountDow.flags || []).join('|');
  c.finalDailyBudget = final;

  // Pause rows carry no budget change
  if (c.recommendationType === 'PAUSE_CAMPAIGN') {
    c.finalDailyBudget = base;
    return;
  }

  // If the overpacing guard reduced a proposed decrease to the current live
// budget, there is no actual dollar change left to apply.
const isDecreaseRecommendation = [
  'BUDGET_DECREASE',
  'BUDGET_DECREASE_APPROVAL'
].includes(c.recommendationType);

if (
  overpacingAccountGuard &&
  isDecreaseRecommendation &&
  c.finalDailyBudget >= c.currentDailyBudget
) {
  c.recommendationType = 'NO_CHANGE';
  c.skipReason = 'DOW_CLAMPED_OVERPACE_NO_CHANGE';
  c.dowNote =
    'DOW increase suppressed because the account is overpacing';
  return;
}

  // Convert eligible NO_CHANGE rows to DOW_ADJUSTMENT when the shaped
  // budget meaningfully differs from the budget that is LIVE right now.
  // This is what lets the daily shape fire on ACCOUNT_ON_TRACK days
  // (Bill's call: allocate toward converting days even when pacing is fine).
  if (c.recommendationType === 'NO_CHANGE'
      && !DOW_CONVERT_EXCLUSIONS.includes(c.skipReason)) {
    const liveBudget = c.currentDailyBudget;
    const dollarDelta = Math.abs(final - liveBudget);
    const pctDelta = liveBudget > 0 ? dollarDelta / liveBudget : (final > 0 ? 1 : 0);
    if (dollarDelta >= 3 || pctDelta >= 0.05) {
      c.recommendationType = 'DOW_ADJUSTMENT';
      c.dowNote = 'Day-of-week shaping: base $' + base + ' x ' + dowM + ' -> $' + final;
    }
  }
});

// Rebuild action buckets after shared budget grouping + DOW transform
actions.autoApply = [];
actions.needsApproval = [];
actions.pauseList = [];

actions.log.forEach(c => {
  if (c.recommendationType === 'PAUSE_CAMPAIGN') {
    actions.pauseList.push(c);
  } else if (c.recommendationType.includes('APPROVAL')) {
    actions.needsApproval.push(c);
  } else if (c.recommendationType === 'BUDGET_INCREASE'
      || c.recommendationType === 'BUDGET_DECREASE'
      || c.recommendationType === 'DOW_ADJUSTMENT') {
    actions.autoApply.push(c);
  }
});

// INVESTIGATE: off-pace but nothing actionable (original logic preserved as fallback)
const pacingAutoApply = actions.autoApply.filter(c => c.recommendationType !== 'DOW_ADJUSTMENT');
const nothingToAct =
  pacingAutoApply.length === 0 &&
  actions.needsApproval.length === 0 &&
  actions.pauseList.length === 0;

const isOffPace = effectiveSeverity !== 'OK' && effectiveSeverity !== 'INVESTIGATE';

const finalSeverity = (nothingToAct && isOffPace)
  ? 'INVESTIGATE'
  : effectiveSeverity;

return {
  json: {
    practiceName: account.practiceName,
    adsId: account.adsId,
    severity: finalSeverity,
    displayStatus: account.displayStatus,   // display-only, untouched by routing (INVESTIGATE etc.)
    date: account.date,
    dow: account.dow,
    pacing: account.pacing,
    projection: account.projection,
    dateContext: account.dateContext,
    accountOnTrack,
    allDemandLimited,
    anyBudgetLimited,
    skipReason,
    // Phase 4: pass steering mode through for the portal + status writer
    campaignSteering: account.campaignSteering || {
      eligible: false, effectiveMode: 'account', statusReason: 'not_managed'
    },
    actions,
    summary: {
      autoApplyCount: actions.autoApply.length,
      approvalCount: actions.needsApproval.length,
      pauseCount: actions.pauseList.length
    }
  }
};

const rows = $input.all();

// Group all rows by google_ads_id
const byAccount = {};

for (const row of rows) {
  const d = row.json;
  const accountId = String(d.google_ads_id || '').trim();
  if (!accountId) continue;

  if (!byAccount[accountId]) {
    byAccount[accountId] = {
        google_ads_id: Number(accountId),
        customer_id: Number(accountId),  // ← add this line
        yesterdays_account_proposed_daily_budget: 0,
        yesterdays_campaigns: {}
    };
  }

  const cId = String(d.campaign_id || '').trim();
  if (cId) {
    byAccount[accountId].yesterdays_campaigns[cId] = {
      proposedDailyBudget: Number(d.campaign_proposed_daily_budget) || 0,
      currentDailyBudget: Number(d.campaign_current_daily_budget) || 0,
      recommendationType: d.recommendation_type || null
    };
  }

  const acctProposed = Number(d.account_proposed_daily_budget);
  if (acctProposed > 0) {
    byAccount[accountId].yesterdays_account_proposed_daily_budget = acctProposed;
  }
}

// Output one item per account
return Object.values(byAccount).map(account => ({ json: account }));

// Group split-out items by customer.id
const grouped = {};

for (const item of $input.all()) {
  const customerId = item.json.customer?.id;
  if (!customerId) continue;

  if (!grouped[customerId]) {
    grouped[customerId] = {
      customer_id: Number(customerId),
      google_ads_id: Number(customerId),  // ← add this line
  sevenDayCampaigns: []
    };
  }

  grouped[customerId].sevenDayCampaigns.push({
    campaign_id: item.json.campaign.id,
    campaign_name: item.json.campaign.name,
    cost_micros: item.json.metrics.costMicros,
    budget_micros: item.json.campaignBudget.amountMicros,
    date: item.json.segments.date
  });
}

return Object.values(grouped).map(g => ({ json: g }));

// Rewrite of the Compute Status branch: read the steering verdict that Merged Data
// ALREADY computed (single source of truth) instead of recomputing coverage/shared/drift.
//
// Merged Data items are ACCOUNT-level. Per-account verdict = j.campaignSteering
// ({ eligible, effectiveMode, statusReason, managedIntent, configuredCount, enabledCount,
//    perCampaignReason }).
// Per-campaign rows live under actions.log[]; a campaign is "configured" iff it was given a
// per-campaign target upstream (campaignMonthlyTarget != null, set in Data for Pacing Agent).
//
// Status tab contract (gid 1124903656): campaign_id | effective_mode | status_reason | last_evaluated
// One row per CONFIGURED campaign on a MANAGED account. Account-level-only accounts emit nothing.
//
// PHASE 5: status_reason is now PER CAMPAIGN. On a fallen-back account each configured campaign
// reports its own cause (drift / shared_budget), sum_overshoot is account-wide, and a campaign
// that is individually fine but blocked by a broken sibling reports blocked_by_sibling.

const items = $input.all();
const now = new Date().toISOString();
const statusRows = [];

for (const item of items) {
  const j = item.json || item;
  const steering = j.campaignSteering || {};

  // Only accounts the operator intends to manage produce status rows.
  if (steering.managedIntent !== true) continue;

  const effectiveMode   = steering.effectiveMode || 'account';
  const accountReason    = steering.statusReason  || 'good';
  const accountEligible  = steering.eligible === true;
  const perCampaign      = steering.perCampaignReason || {};

  const log = (j.actions && Array.isArray(j.actions.log)) ? j.actions.log : [];

  for (const c of log) {
    // "Configured" = this campaign carries an operator target (has a config row).
    const configured = c && c.campaignMonthlyTarget != null;
    if (!configured) continue;

    const cid = c.campaignId != null ? String(c.campaignId) : '';
    if (!cid) continue;

    // PHASE 5 — per-campaign reason resolution
    let reason;
    if (accountEligible) {
      reason = 'good'; // account is steering; every configured campaign is good
    } else {
      const own = perCampaign[cid]; // 'drift' | 'shared_budget' | 'ok' | undefined
      if (own === 'drift')              reason = 'drift';
      else if (own === 'shared_budget') reason = 'shared_budget';
      else if (accountReason === 'sum_overshoot') reason = 'sum_overshoot';
      else                              reason = 'blocked_by_sibling'; // this one's fine; a sibling broke it
    }

    statusRows.push({
      json: {
        campaign_id: cid,
        effective_mode: effectiveMode,
        status_reason: reason,
        last_evaluated: now
      }
    });
  }
}

return statusRows;

// ============================================================================
// Build Account Rows  (v2 — closes defects 1 and 3)
// ============================================================================
// Emits ONLY rows belonging to the account in this webhook payload.
// Every other account's rows are never read into the output, never rewritten,
// and therefore cannot be lost by a concurrent run.
//
// Match key downstream is `campaign_id`, globally unique in Google Ads.
//
// --- REMOVAL IS EXPLICIT, NEVER INFERRED -----------------------------------
// A campaign is tombstoned if and only if the portal names it in
// `removed_campaign_ids`. Absence from `campaigns[]` means nothing — the portal
// legitimately filters campaigns out (shared-budget campaigns are excluded from
// the managed set).
//
// --- v2 CHANGES -------------------------------------------------------------
// DEFECT 1 — `managed` was unreachable when `campaigns[]` was empty, so an
//   operator could not unmanage an account from the portal. `managed` is an
//   ACCOUNT-level flag stored per row, so it is now swept across ALL of the
//   account's existing non-tombstoned rows on every save. Nothing is deleted or
//   tombstoned by the sweep; only `managed` (+ snapshot) and the audit stamps
//   change. `budget_dollars` is preserved exactly as read.
//   `managed` must now be sent EXPLICITLY — a missing/unparseable value throws
//   rather than defaulting to FALSE, because defaulting would unmanage the whole
//   account on any save that omitted the key.
//
// DEFECT 3 — `account_monthly_budget_snapshot` was silently dropped. It is now
//   mapped through to its own column (append it to the RIGHT of `active`).
//   It is OPTIONAL: when the payload omits it, each row keeps whatever value it
//   already had, so a portal that doesn't send it can never blank the column.
//
// NOTE ON DEFECT 2 (500 on a legitimate no-op): NOT fixed here. Returning zero
//   items is still possible — see the change package for the two options. The
//   sweep does shrink the no-op window substantially: any save that changes
//   `managed` or the snapshot on an account with existing rows now emits rows.
// ============================================================================

const inc = $('Campaign Budget Updates').first().json.body || {};
const acct = inc.google_ads_id != null ? String(inc.google_ads_id).trim() : '';
const now = new Date().toISOString();

// --- Payload guards: refuse to write rather than corrupt the tab ------------
if (!acct) {
  throw new Error(
    'Campaign Budget Updates: payload is missing google_ads_id. Refusing to write.'
  );
}
if (!Array.isArray(inc.campaigns)) {
  throw new Error(
    'Campaign Budget Updates: payload.campaigns is not an array. Refusing to write ' +
    '(account ' + acct + ').'
  );
}
if (inc.removed_campaign_ids != null && !Array.isArray(inc.removed_campaign_ids)) {
  throw new Error(
    'Campaign Budget Updates: removed_campaign_ids is present but is not an array ' +
    '(account ' + acct + '). Refusing to write.'
  );
}

// `managed` must be explicit. It is now applied to every row of the account, so
// silently defaulting a missing value to FALSE would unmanage the whole account.
// Accepts booleans and the strings true/false in any case. Anything else throws.
let managedFlag;
if (inc.managed === true || inc.managed === false) {
  managedFlag = inc.managed ? 'TRUE' : 'FALSE';
} else if (typeof inc.managed === 'string' && /^(true|false)$/i.test(inc.managed.trim())) {
  managedFlag = inc.managed.trim().toUpperCase();
} else {
  throw new Error(
    'Campaign Budget Updates: `managed` must be sent as an explicit boolean ' +
    '(got ' + JSON.stringify(inc.managed) + ', account ' + acct + '). Refusing to write — ' +
    'defaulting it would unmanage every campaign on this account.'
  );
}

const updatedBy = inc.updated_by != null ? inc.updated_by : '';
const practiceName = inc.practice_name != null ? inc.practice_name : '';

// Optional account-level snapshot. Absent → preserve each row's existing value.
const hasSnapshot = inc.account_monthly_budget_snapshot != null &&
                    String(inc.account_monthly_budget_snapshot).trim() !== '';
const snapshotIn = hasSnapshot ? inc.account_monthly_budget_snapshot : null;

// Explicit removal list. Absent key → empty set → nothing is tombstoned.
const removedIds = new Set(
  (inc.removed_campaign_ids || [])
    .map(x => String(x != null ? x : '').trim())
    .filter(Boolean)
);

// --- Index this account's existing rows -------------------------------------
// Used to (a) resolve a missing snapshot per row, (b) drive the managed sweep.
const existingByCid = new Map();
for (const item of $input.all()) {
  const r = (item && item.json) || {};
  if (String(r.google_ads_id != null ? r.google_ads_id : '').trim() !== acct) continue;
  const cid = String(r.campaign_id != null ? r.campaign_id : '').trim();
  if (cid === '') continue;
  existingByCid.set(cid, r);
}

const norm = v => String(v != null ? v : '').trim().toUpperCase();
const isTombstoned = r => norm(r.active !== undefined && r.active !== '' ? r.active : 'TRUE') === 'FALSE';

// Resolve the snapshot for a row: payload value wins, else keep what's there.
function resolveSnapshot(existingRow) {
  if (hasSnapshot) return snapshotIn;
  if (existingRow && existingRow.account_monthly_budget_snapshot != null) {
    return existingRow.account_monthly_budget_snapshot;
  }
  return '';
}

// --- 1. LIVE rows from the incoming payload --------------------------------
const rows = [];
const seen = new Set();

for (const c of inc.campaigns) {
  if (!c) continue;
  const cid = String(c.campaign_id != null ? c.campaign_id : '').trim();
  if (cid === '') continue;
  if (seen.has(cid)) continue; // payload sent the same campaign twice

  // A campaign cannot be both sent and declared removed. Sent wins, loudly.
  if (removedIds.has(cid)) {
    throw new Error(
      'Campaign Budget Updates: campaign ' + cid + ' appears in both campaigns[] and ' +
      'removed_campaign_ids (account ' + acct + '). Refusing to write.'
    );
  }

  seen.add(cid);
  rows.push({
    google_ads_id: acct,
    practice_name: practiceName,
    campaign_id: cid,
    campaign_name: c.campaign_name != null ? c.campaign_name : '',
    budget_dollars: c.budget_dollars,
    managed: managedFlag,
    updated_by: updatedBy,
    updated_at: now,
    active: 'TRUE',
    account_monthly_budget_snapshot: resolveSnapshot(existingByCid.get(cid))
  });
}

// --- 2. TOMBSTONE only the campaigns the portal explicitly declared removed --
if (removedIds.size > 0) {
  for (const [cid, r] of existingByCid) {
    if (!removedIds.has(cid)) continue; // not declared removed — leave it alone
    if (seen.has(cid)) continue;
    if (isTombstoned(r)) continue;      // already tombstoned — don't rewrite

    seen.add(cid);
    rows.push({
      google_ads_id: acct,
      practice_name: r.practice_name != null ? r.practice_name : practiceName,
      campaign_id: cid,          // PRESERVED — this is the upsert match key
      campaign_name: r.campaign_name != null && r.campaign_name !== ''
        ? r.campaign_name
        : cid,
      budget_dollars: '',
      managed: 'FALSE',
      updated_by: updatedBy,
      updated_at: now,
      active: 'FALSE',
      account_monthly_budget_snapshot: resolveSnapshot(r)
    });
  }
}

// --- 3. SWEEP `managed` (+ snapshot) across the account's remaining rows -----
// DEFECT 1 FIX. `managed` is account-level; every live row of the account must
// agree with the flag the operator just sent. Without this, unchecking "managed"
// with an empty campaigns[] wrote nothing and the account stayed managed forever.
//
// Deliberately conservative: skips tombstones, preserves budget_dollars and
// campaign_name verbatim, and writes nothing when the row already agrees.
for (const [cid, r] of existingByCid) {
  if (seen.has(cid)) continue;   // already emitted above
  if (isTombstoned(r)) continue; // tombstones stay as they are

  const managedDiffers = norm(r.managed) !== managedFlag;
  const snapDiffers = hasSnapshot &&
    String(r.account_monthly_budget_snapshot != null ? r.account_monthly_budget_snapshot : '').trim()
      !== String(snapshotIn).trim();

  if (!managedDiffers && !snapDiffers) continue; // nothing to change — no write

  seen.add(cid);
  rows.push({
    google_ads_id: acct,
    practice_name: r.practice_name != null && r.practice_name !== '' ? r.practice_name : practiceName,
    campaign_id: cid,
    campaign_name: r.campaign_name != null ? r.campaign_name : '',
    budget_dollars: r.budget_dollars != null ? r.budget_dollars : '', // PRESERVED
    managed: managedFlag,
    updated_by: updatedBy,
    updated_at: now,
    active: 'TRUE',
    account_monthly_budget_snapshot: resolveSnapshot(r)
  });
}

// Nothing to do → touch the sheet zero times.
// NOTE: this is the path that produces the defect-2 false 500 under
// responseMode: lastNode. See the change package for the fix options.
if (rows.length === 0) return [];

return rows.map(json => ({ json }));
